<script lang="ts">
 import {onMount} from 'svelte';import type {BoardSummary,Board,TransferPreview} from './types';
 let {boards,onload,onpreview,oncommit,onverify,onrecover,onclose}:{boards:BoardSummary[];onload:(id:number)=>Promise<Board>;onpreview:(b:number,l:number)=>Promise<TransferPreview>;oncommit:()=>Promise<void>;onverify:()=>Promise<string>;onrecover:(result:string)=>Promise<void>;onclose:()=>void}=$props();
 let target=$state(''),list=$state(''),snapshot=$state<Board|null>(null),preview=$state<TransferPreview|null>(null),working=$state(false),message=$state(''),unknown=$state(false),verification=$state(''),ack=$state(false),panel:HTMLDivElement;let seq=0;
 onMount(()=>{const previous=document.activeElement as HTMLElement,shell=document.querySelector<HTMLElement>('.app-shell');if(shell)shell.inert=true;panel.focus();const keys=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!unknown&&!working)onclose();if(e.key==='Tab'){const nodes=Array.from(panel.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)'));if(e.shiftKey&&(document.activeElement===nodes[0]||document.activeElement===panel)){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}};document.addEventListener('keydown',keys);return()=>{++seq;if(shell)shell.inert=false;document.removeEventListener('keydown',keys);if(previous?.isConnected)previous.focus()}});
 async function select(){const token=++seq;preview=null;ack=false;snapshot=null;list='';if(!target)return;working=true;try{const b=await onload(Number(target));if(token!==seq)return;snapshot=b;list=String(b.lists[0]?.id||'')}catch(e){message=String(e)}finally{if(token===seq)working=false}}
 async function prepare(){preview=null;ack=false;message='';working=true;try{const fresh=await onpreview(Number(target),Number(list));const current=await onload(Number(target));snapshot=current;if(current.revision!==fresh.target_revision||!current.lists.some(l=>l.id===fresh.target_list_id))throw new Error('目标看板已更新，请重新获取预览并确认');preview=fresh}catch(e){message=e instanceof Error?e.message:'预览失败'}finally{working=false}}
 async function commit(){working=true;message='';try{await oncommit()}catch(e){unknown=!(e as any).status||(e as any).status>=500;message=unknown?'转移结果未知。未自动重试，其他写入已阻塞。请只读核对全部原任务 ID 的源和目标归属。':(e as Error).message+'。原输入与重复规则保留；请重新预览并确认。';preview=null;ack=false}finally{working=false}}
</script>
<div class="transfer-shade"><div class="dialog transfer-dialog" role="dialog" aria-modal="true" aria-labelledby="transfer-title" tabindex="-1" bind:this={panel}><h2 id="transfer-title">移入普通看板 · 整条重复链</h2><p>保留任务 ID、日期、重复规则与所有附属记录，不支持移回收集箱。</p>
 {#if message}<div class="alert" role="alert">{message}</div>{/if}
 {#if unknown}<button disabled={working} onclick={async()=>{working=true;try{verification=await onverify()}catch(e){message=String(e)}finally{working=false}}}>只读核对源与目标</button>{#if verification}<p role="status">{verification==='moved'?'全部任务已在目标，源路径已不可用。':verification==='source'?'全部任务仍在源收集箱，目标路径不可用。':'暂时无法确定；保持写入阻塞，不会自动重放。'}</p>{#if verification!=='uncertain'}<button disabled={working} onclick={()=>onrecover(verification)}>确认核对结果并恢复</button>{/if}{/if}
 {:else}<label>目标看板<select aria-label="转移目标看板" bind:value={target} onchange={select} disabled={working}><option value="">选择看板</option>{#each boards as b}<option value={String(b.id)}>{b.title}</option>{/each}</select></label><label>目标列表<select aria-label="转移目标列表" bind:value={list} disabled={working||!snapshot} onchange={()=>{preview=null;ack=false}}>{#each snapshot?.lists||[] as l}<option value={String(l.id)}>{l.title}</option>{/each}</select></label>
 <button disabled={working||!target||!list} onclick={prepare}>{working?'请稍候…':'获取最新完整预览'}</button>
 {#if preview}<section class="transfer-summary"><h3>{snapshot?.title} / {snapshot?.lists.find(l=>l.id===Number(list))?.title}</h3><p>{preview.task_count} 个历史和当前任务（其中已归档 {preview.archived_count} 个，已完成 {preview.completed_count} 个）</p><p>{preview.comment_count} 条评论 · {preview.checklist_count} 条清单条目 · {preview.attachment_count} 条附件记录（含已删除元数据） · {preview.attachment_bytes} 字节非删除附件</p><p>包括整条重复链的历史、当前与已归档任务，标题、描述、日期与重复设置、清单、评论和附件。转移后，以上内容对目标看板的全部现有及未来成员可见，包括重新启用的成员。未来生成的后继也在目标看板。无法收回已经看过的内容。</p><label class="checkbox"><input type="checkbox" aria-label="确认整链可见范围" bind:checked={ack}/>我确认此完整可见范围</label><button class="primary" disabled={!ack||working} onclick={commit}>确认整链转移</button></section>{/if}
 <button disabled={working} onclick={onclose}>取消</button>{/if}
</div></div>
